  "claims": [
    {
      "claim": "Andrographolide, a diterpenoid lactone, showed poor oral bioavailability after oral administration in human volunteers, supporting low F for the query's structurally similar diterpenoid acid scaffold.",
      "card_ids": ["C13"]
    },
    {
      "claim": "Docetaxel, a diterpenoid, has low absolute oral bioavailability in humans due to CYP3A-mediated first-pass extraction, a mechanism likely relevant to the query's complex diterpenoid scaffold.",
      "card_ids": ["C08"]
    },
    {
      "claim": "Withaferin A, a polycyclic steroidal lactone, showed poor oral bioavailability in humans, supporting low F for the query's polycyclic natural product core.",
      "card_ids": ["C10"]
    },
    {
      "claim": "Mometasone, a corticosteroid with molecular weight similar to the query, has very low oral bioavailability (<1%), supporting low F for the query's steroid-like core.",
      "card_ids": ["C02", "C04"]
    },
    {
      "claim": "Aneortave desacetate and fluticasone, both steroid-like molecules, showed low or negligible oral bioavailability in humans, further supporting low F for the query.",
      "card_ids": ["C05", "C07"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "current_gold_voting_records",
      "applicability": "high",
      "direction": "supportive",
      "decision_effect": "changed",
      "card_ids": ["C13", "C08", "C10", "C02", "C04", "C05", "C07"]
    }
  ],
  "evidence_gaps": [
    "No direct experimental oral bioavailability measurement for the query molecule.",
    "Transfer from structural analogs is qualitative; no exact structural match is present.",
    "No formulation, dose, or food-effect information is available for the query.",
    "Potential roles of efflux transporters or CYP3A in the query are inferred, not directly measured.",
    "The query's carboxylic acid and ester may undergo hydrolysis or first-pass metabolism, but this is not directly evidenced."
  ],
  "decision_summary": "The query is a complex polycyclic diterpenoid acid with high molecular weight, multiple hydrogen-bond donors/acceptors, and an ionizable carboxylic acid. Multiple transferable L1 records for structurally similar diterpenoid/steroid natural products (andrographolide, docetaxel, withaferin A, mometasone, anecortave, fluticasone) report poor to negligible oral bioavailability. No affirmative evidence supports F >= 20%, so the prediction is low."
}

